/* Fechar porta — Tiago's Toolkit: Sons */
const PASTA = "modules/tiagos-toolkit-sons/audio/";
const sorteia = l => l[Math.floor(Math.random() * l.length)];
const toca = (clips, volume) => foundry.audio.AudioHelper.play(
  { src: `${PASTA}${sorteia(clips)}.mp3`, volume, autoplay: true, loop: false, channel: "interface" }, true);

toca(["porta-fechar-1", "porta-fechar-2", "porta-fechar-3", "porta-fechar-4"], 1);
